export const LADDER_STEPS=[{"title":"Önce kaçışları say","text":"Merdiven (Japonca shichō), kaçan grubu art arda atariye alarak kurulan zikzak bir takip dizisidir. Önce beyazın iki nefesini tahtada bul.","mode":"liberties"},{"title":"Atarinin yönünü seç","text":"Siyah olarak beyazı atariye al. İki nefesten hangisini kapatırsan beyaz zikzak kaçışa zorlanır? Diğer yönü de deneyebilirsin.","mode":"first"},{"title":"Zorunlu kaçışı bul","text":"Beyazın yalnız bir nefesi kaldı. Beyaz olarak grubu uzat; sonra yeni grubun nefeslerini say.","mode":"escape"},{"title":"Kaçış → atari ritmi","text":"Beyaz uzayınca iki nefes kazanır. Siyah doğru taraftan beyazı atariye alarak nefeslerini yeniden bire indirir. İlk üç hamle çiftini yavaşça izle.","mode":"rhythm"},{"title":"Merdiveni sen sürdür","text":"Siyah olarak beyazı üç kez daha atariye al. Beyaz tek nefesinden otomatik olarak kaçacak. Her hamlenden önce iki olası yönü karşılaştır.","mode":"practice"},{"title":"Kenarda son nefes","text":"Merdiveni başlangıçtan kenara kadar izle. Beyazın son kaçışı ikinci bir nefes açmayacak. O anda siyah olarak bütün beyaz zinciri yakala.","mode":"capture"},{"title":"Merdiven kırıcı","text":"Aynı başlangıç, aynı takip yönü; bu kez ileride bir beyaz destek taşı var. Kovalamaya başlamadan önce sonucunu düşün.","mode":"breaker"},{"title":"Destek taşının yeri","text":"İki işaretli noktadan birine beyaz destek taşı ekle ve kovalamayı izle. Sadece uzakta bir beyaz taş bulunması yeterli mi?","mode":"support"},{"title":"Bütün rotayı oku","text":"Şimdi müfredattaki uzun örneğe geçiyoruz: 13×13 tahtada rota daha uzun. Kırıcı olmadan ve kırıcı taşla iki sonucu karşılaştır.","mode":"long"}];
